83	class LibrarySpec extends AnyFreeSpec with ChiselSim {
84	  "ForceZero when invalid" in {
85	    simulate(new ForceZeroTester) { dut =>
86	      dut.io.in.bits.poke(9001)
87	      dut.io.in.valid.poke(0)
