177	  "ShiftVectorLeft" in {
178	    simulate(new ShiftVectorLeftTester) { dut =>
179	      val valids = Seq.fill(16)(Random.between(0, 2))
180	      val data = Seq.fill(16)(Random.between(0, 2147483647))
181	      for (i <- 0 until 16) {
182	        dut.io.in(i).valid.poke(valids(i))
183	        dut.io.in(i).bits.poke(data(i))
184	      }
185	
186	      for (t <- 0 until 16) {
187	        dut.io.shift.poke(t)
188	        for (o <- 0 until 16) {
189	          var targetIndex = o + t
190	          if (targetIndex >= 16) {
191	            targetIndex = targetIndex - 16
192	          }
193	          if (targetIndex < o) {
194	            dut.io.out(targetIndex).valid.expect(0.U.asTypeOf(dut.io.out(0).valid))
195	            dut.io.out(targetIndex).bits.expect(0.U.asTypeOf(dut.io.out(0).bits))
