package common

import chisel3._
import chisel3.util._

/** Input command: ina * inb + inc */
class FmaCmd extends Bundle {
  val ina = new Fp32
  val inb = new Fp32
  val inc = new Fp32
}

/** Result of Stage 1: product of ina * inb, normalized.
  *
  * Fields:
  *  - prodSign:     sign of the product
  *  - prodExp:      exponent of the product (biased, 9 bits to handle overflow)
  *  - prodMantissa: 24-bit significand (bit 23 = implicit 1)
  *  - isZero:       product is zero
  *  - isInf:        product is infinity
  *  - isNan:        product is NaN
  *  - incSign, incExp, incMantissa: passthrough of inc (addend)
  */
class FmaState1 extends Bundle {
  val prodSign     = Bool()
  val prodExp      = UInt(9.W)   // enough bits for biased exponent (0..382)
  val prodMantissa = UInt(24.W)  // with implicit leading 1
  val isZero       = Bool()
  val isInf        = Bool()
  val isNan        = Bool()
  val incSign      = Bool()
  val incExp       = UInt(8.W)
  val incMantissa  = UInt(24.W)  // with implicit leading 1
  val incIsZero    = Bool()
  val incIsInf     = Bool()
  val incIsNan     = Bool()
}

/** Result of Stage 2: aligned operands for addition.
  *
  *  Both operands are aligned to the same exponent (the larger one).
  *  - resultExp:   the common exponent
  *  - prodAligned: 27-bit aligned product significand (with guard/round/sticky)
  *  - incAligned:  27-bit aligned inc significand
  *  - prodSign, incSign: signs of the two operands
  *  - isZero, isInf, isNan: special case flags
  */
class FmaState2 extends Bundle {
  val resultExp   = UInt(9.W)
  val prodAligned = UInt(27.W)   // 24-bit mantissa + 3 guard bits
  val incAligned  = UInt(27.W)
  val prodSign    = Bool()
  val incSign     = Bool()
  val isZero      = Bool()
  val isInf       = Bool()
  val isNan       = Bool()
}

object Fma {

  /** Stage 1: Compute the product ina * inb.
    *
    * Returns a FmaState1 with the normalized product and the passthrough addend.
    */
  def FmaStage1(cmd: FmaCmd): FmaState1 = {
    val s1 = Wire(new FmaState1)

    val ina = cmd.ina
    val inb = cmd.inb
    val inc = cmd.inc

    // Detect specials
    val aIsZero = ina.isZero()
    val bIsZero = inb.isZero()
    val aIsInf  = ina.isInf()
    val bIsInf  = inb.isInf()
    val aIsNan  = ina.isNan()
    val bIsNan  = inb.isNan()

    val prodIsNan  = aIsNan || bIsNan || (aIsInf && bIsZero) || (aIsZero && bIsInf)
    val prodIsInf  = !prodIsNan && (aIsInf || bIsInf)
    val prodIsZero = !prodIsNan && !prodIsInf && (aIsZero || bIsZero)

    s1.isNan  := prodIsNan
    s1.isInf  := prodIsInf
    s1.isZero := prodIsZero

    s1.prodSign := ina.sign ^ inb.sign

    // Significands with implicit leading 1 (24 bits each)
    val sigA = Cat(1.U(1.W), ina.mantissa)  // 24 bits
    val sigB = Cat(1.U(1.W), inb.mantissa)  // 24 bits

    // Product is up to 48 bits
    val product = sigA * sigB  // 48-bit result

    // Normalize: product is either in [2^46, 2^47) or [2^47, 2^48)
    // (since each sig is in [2^23, 2^24) )
    // Raw exponent = ina.exp + inb.exp - 127
    val rawExp = ina.exponent +& inb.exponent  // 9-bit sum

    // If MSB is at bit 47: shift = 24, exp_adj = 1
    // If MSB is at bit 46: shift = 23, exp_adj = 0
    val highBit = product(47)  // 1 if product >= 2^47

    val prodMantissa = Wire(UInt(24.W))
    val prodExp      = Wire(UInt(9.W))

    when(highBit) {
      // Shift right 24: take bits [47:24]
      prodMantissa := product(47, 24)
      prodExp      := rawExp - 127.U + 1.U
    }.otherwise {
      // Shift right 23: take bits [46:23]
      prodMantissa := product(46, 23)
      prodExp      := rawExp - 127.U
    }

    s1.prodMantissa := prodMantissa
    s1.prodExp      := Mux(prodIsZero || prodIsNan || prodIsInf, 0.U, prodExp)

    // Passthrough inc
    s1.incSign     := inc.sign
    s1.incExp      := inc.exponent
    s1.incMantissa := Cat(1.U(1.W), inc.mantissa)
    s1.incIsZero   := inc.isZero()
    s1.incIsInf    := inc.isInf()
    s1.incIsNan    := inc.isNan()

    s1
  }

  /** Stage 2: Align the product and the addend to the same exponent.
    *
    * The larger exponent is kept; the smaller operand is shifted right.
    * We use 27 bits (24 + 3 guard bits) to preserve rounding information.
    */
  def FmaStage2(s1: FmaState1): FmaState2 = {
    val s2 = Wire(new FmaState2)

    s2.isZero := s1.isZero
    s2.isInf  := s1.isInf
    s2.isNan  := s1.isNan
    s2.prodSign := s1.prodSign
    s2.incSign  := s1.incSign

    // Special case: inc is zero -> just use product (shifted to 27-bit space)
    // Special case: product is zero -> use inc

    // Extended significands with 3 guard bits
    val prodSig27 = Cat(s1.prodMantissa, 0.U(3.W))  // 27 bits
    val incSig27  = Cat(s1.incMantissa,  0.U(3.W))  // 27 bits

    // Compare exponents to determine alignment
    // prodExp is 9-bit signed (but always non-negative in valid range)
    // incExp is 8-bit
    val prodExpS = s1.prodExp  // 9 bits
    val incExpU  = s1.incExp   // 8 bits

    // prodExp >= incExp: shift inc right by (prodExp - incExp)
    // prodExp < incExp: shift prod right by (incExp - prodExp)

    // Clamp shift to 27 (beyond that, the shifted value is all zeros)
    val prodGtInc = prodExpS >= incExpU

    val shiftAmt = Wire(UInt(9.W))
    shiftAmt := Mux(prodGtInc,
      prodExpS - incExpU,
      incExpU - prodExpS)

    val shiftClamped = Mux(shiftAmt > 27.U, 27.U, shiftAmt)

    val prodAligned = Wire(UInt(27.W))
    val incAligned  = Wire(UInt(27.W))
    val resultExp   = Wire(UInt(9.W))

    when(prodGtInc) {
      // Product has larger exponent; shift inc right
      incAligned  := (incSig27 >> shiftClamped)(26, 0)
      prodAligned := prodSig27
      resultExp   := prodExpS
    }.otherwise {
      // Inc has larger (or equal) exponent; shift prod right
      prodAligned := (prodSig27 >> shiftClamped)(26, 0)
      incAligned  := incSig27
      resultExp   := incExpU
    }

    // Handle zero cases: if one is zero, alignment doesn't matter
    s2.prodAligned := Mux(s1.isZero || s1.isNan, 0.U, prodAligned)
    s2.incAligned  := Mux(s1.incIsZero || s1.incIsNan, 0.U, incAligned)
    s2.resultExp   := Mux(s1.isZero, Mux(s1.incIsZero, 0.U, incExpU), Mux(s1.incIsZero, prodExpS, resultExp))

    s2
  }

  /** Stage 3: Add/subtract aligned significands, normalize, produce Fp32 output. */
  def FmaStage3(s2: FmaState2): Fp32 = {
    val out = Wire(new Fp32)

    // Handle special cases
    when(s2.isNan) {
      // NaN: sign=0, exp=0xFF, mantissa!=0
      out.sign     := 0.U
      out.exponent := 0xFF.U
      out.mantissa := 1.U
    }.elsewhen(s2.isInf) {
      out.sign     := s2.prodSign
      out.exponent := 0xFF.U
      out.mantissa := 0.U
    }.otherwise {
      // Normal computation: add or subtract based on signs
      val sameSign = s2.prodSign === s2.incSign

      // 28-bit addition space (27 bits + carry)
      val sumRaw = Wire(UInt(28.W))
      val resultSign = Wire(Bool())

      when(sameSign) {
        // Add magnitudes; sign = common sign
        sumRaw     := s2.prodAligned +& s2.incAligned
        resultSign := s2.prodSign
      }.otherwise {
        // Subtract: result = |larger| - |smaller|
        // Determine which is larger
        when(s2.prodAligned >= s2.incAligned) {
          sumRaw     := s2.prodAligned - s2.incAligned
          resultSign := s2.prodSign
        }.otherwise {
          sumRaw     := s2.incAligned - s2.prodAligned
          resultSign := s2.incSign
        }
      }

      // Normalize the result
      // sumRaw is 28 bits; the normalized significand has MSB at bit 23 (of 24-bit sig)
      // which corresponds to bit 26 of sumRaw (27-bit mantissa+guard space)
      // Possible cases:
      //   bit 27 set: overflow from addition -> shift right 1, exp++
      //   bit 26 set: normalized
      //   bit 25..0 set: need to shift left by (26 - MSBpos)

      val baseExp = s2.resultExp

      // Find the result exponent and mantissa
      // MSB detection using a priority encoder
      val msbPos = Wire(UInt(5.W))
      msbPos := 0.U
      for (i <- 0 until 28) {
        when(sumRaw(i)) {
          msbPos := i.U
        }
      }

      val isResultZero = sumRaw === 0.U

      // Where should MSB be? At bit 26 of sumRaw (= bit 23 of 24-bit significand)
      val targetMsb = 26.U

      val finalExp  = Wire(UInt(9.W))
      val finalMant = Wire(UInt(23.W))

      when(isResultZero) {
        finalExp  := 0.U
        finalMant := 0.U
      }.elsewhen(msbPos > targetMsb) {
        // Overflow: msbPos == 27
        // Shift right by (msbPos - targetMsb) = 1
        val shiftR = msbPos - targetMsb
        val shifted = sumRaw >> shiftR
        finalMant := shifted(22, 0)
        val newExp = baseExp + shiftR
        // Check for exponent overflow (infinity)
        when(newExp >= 255.U) {
          finalExp  := 255.U
          finalMant := 0.U
        }.otherwise {
          finalExp := newExp(7, 0)
        }
      }.elsewhen(msbPos === targetMsb) {
        // Already normalized
        finalMant := sumRaw(22, 0)
        when(baseExp === 0.U || baseExp >= 255.U) {
          finalExp  := Mux(baseExp >= 255.U, 255.U, 0.U)
          finalMant := 0.U
        }.otherwise {
          finalExp := baseExp(7, 0)
        }
      }.otherwise {
        // Need to shift left (subtraction result)
        val shiftL = targetMsb - msbPos
        val shifted = (sumRaw << shiftL)(26, 0)
        finalMant := shifted(22, 0)
        // Exponent decreases by shiftL; if underflow, clamp to zero
        when(baseExp <= shiftL) {
          finalExp  := 0.U
          finalMant := 0.U
        }.otherwise {
          val newExp = baseExp - shiftL
          when(newExp >= 255.U) {
            finalExp  := 255.U
          }.otherwise {
            finalExp := newExp(7, 0)
          }
        }
      }

      out.sign     := resultSign
      out.exponent := finalExp(7, 0)
      out.mantissa := finalMant
    }

    out
  }
}

