  def apply[T <: Data](v: Vec[T], shift: UInt): Vec[T] = {
    val n = v.length
    VecInit(Seq.tabulate(n) { j =>
      // output[j] = input[(j + shift) % n]
      val candidates = Seq.tabulate(n) { s =>
        (s.U -> v((j + s) % n))
      }
      MuxLookup(shift, v(0))(candidates)
    })
  }
}

